function findKthLargest(nums: number[], k: number): number {
  function partition(left: number, right: number, pivotIndex: number): number {
    const pivot = nums[pivotIndex];
    [nums[pivotIndex], nums[right]] = [nums[right], nums[pivotIndex]];

    let storeIndex = left;
    for (let i = left; i < right; i++) {
      if (nums[i] > pivot) {
        [nums[storeIndex], nums[i]] = [nums[i], nums[storeIndex]];
        storeIndex++;
      }
    }

    [nums[right], nums[storeIndex]] = [nums[storeIndex], nums[right]];
    return storeIndex;
  }

  function quickSelect(left: number, right: number): number {
    if (left === right) return nums[left];

    const pivotIndex = Math.floor((left + right) / 2);
    const partitionIndex = partition(left, right, pivotIndex);

    if (partitionIndex === k - 1) return nums[partitionIndex];
    else if (partitionIndex < k - 1) return quickSelect(partitionIndex + 1, right);
    else return quickSelect(left, partitionIndex - 1);
  }

  return quickSelect(0, nums.length - 1);
}

// Time Complexity: O(n) average
// Space Complexity: O(1)
